// Builds one short Telegram alert from n8n's error data: which workflow failed, the step it stopped
// at, the execution number and link, and the time. Nothing from the email or PDF is copied, and the
// error message itself is left out because it can quote data; open the execution in n8n to see it.
const data = $input.first().json || {};
const execution = data.execution || {};
const workflow = data.workflow || {};
const clean = (value, max) => String(value === undefined || value === null ? '' : value)
  .replace(/[\u0000-\u001f\u007f<>&]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const url = clean(execution.url, 300);
const lines = [
  'SIMBA invoice intake failed',
  'Workflow: ' + (clean(workflow.name, 120) || 'unknown'),
  'Stopped at: ' + (clean(execution.lastNodeExecuted, 120) || 'unknown'),
  'Execution: ' + (clean(execution.id, 40) || 'unknown'),
];
if (/^https?:\/\//i.test(url)) lines.push('Open: ' + url);
lines.push('Time: ' + new Date(Date.now() + 8 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19) + ' SGT');
lines.push('Emails in that run may need filing by hand; see the SIMBA runbook, "Failures".');
return [{ json: { alert_text: lines.join('\n') } }];
